import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.YEBM7mz9.js";const p=JSON.parse('{"title":"Architectural Blueprint: The Controlled Handover","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),o={name:"architecture.md"};function n(i,e,l,h,u,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="architectural-blueprint-the-controlled-handover" tabindex="-1">Architectural Blueprint: The Controlled Handover <a class="header-anchor" href="#architectural-blueprint-the-controlled-handover" aria-label="Permalink to &quot;Architectural Blueprint: The Controlled Handover&quot;">​</a></h1><p>Building for the web is a balance. Should your page be fast and static, or powerful and interactive? We believe you shouldn&#39;t have to choose.</p><p><code>react-rehydrate</code> is built on the core principle of <strong><a href="https://web.dev/progressive-enhancement/" target="_blank" rel="noreferrer">Progressive Enhancement</a></strong>: start with a solid, high-performance foundation (HTML) and upgrade only what&#39;s necessary (React).</p><hr><h2 id="🧭-which-path-are-you-on" tabindex="-1">🧭 Which path are you on? <a class="header-anchor" href="#🧭-which-path-are-you-on" aria-label="Permalink to &quot;🧭 Which path are you on?&quot;">​</a></h2><p><strong>The &quot;Standard&quot; Way (SPA)</strong><br> The browser downloads a giant JavaScript file. The screen stays white. Then, JavaSript builds the entire page from scratch.<br><em>Results: Fast once loaded, but slow for SEO and first-time users.</em></p><p><strong>The &quot;Rehydrate&quot; Way (Islands)</strong><br> The server sends a fully built HTML page. It&#39;s visible and readable <strong>instantly</strong>. React then &quot;wakes up&quot; only the specific parts that need to be interactive.<br><em>Results: Perfect SEO, instant reading, and powerful interactivity where it counts.</em></p><hr><h2 id="🏛️-the-analogy-the-museum-tour-guide" tabindex="-1">🏛️ The Analogy: The Museum Tour Guide <a class="header-anchor" href="#🏛️-the-analogy-the-museum-tour-guide" aria-label="Permalink to &quot;🏛️ The Analogy: The Museum Tour Guide&quot;">​</a></h2><p>If your website is a <strong>Historic Museum</strong> (your existing site):</p><ol><li><strong>Don&#39;t demolish it.</strong> You don&#39;t need to rebuild the whole building just to add a new interactive exhibit.</li><li><strong>Add &quot;Smart Markers.&quot;</strong> Place a small sign (a data-attribute) where you want a new interactive feature.</li><li><strong>The Tour Guide (Rehydrator).</strong> Our library acts as a guide. It walks through the museum once, finds your markers, and installs your React &quot;exhibits&quot; exactly where they belong.</li></ol><p><strong>The museum stays historic, but the experience feels futuristic.</strong></p><hr><h2 id="🔄-the-3-step-handover" tabindex="-1">🔄 The 3-Step Handover <a class="header-anchor" href="#🔄-the-3-step-handover" aria-label="Permalink to &quot;🔄 The 3-Step Handover&quot;">​</a></h2><p>Our architecture follows a strictly managed sequence. Here is what happens when a user lands on your page:</p><ol><li><strong>Discovery (The Scan):</strong> The library performs a quick scan for your <code>[data-react-from-markup-container]</code> markers.</li><li><strong>Bridge (The Props):</strong> It extracts any data you&#39;ve stored in attributes (like <code>data-count=&quot;5&quot;</code>) and prepares them as props for React.</li><li><strong>Takeover (The Hydration):</strong> React takes control of just that specific section.</li></ol><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as Static HTML</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant R as React Rehydrate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as React Component</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;R: Tells where to look</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;S: Scans for markers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;S: Extracts data/props</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R-&gt;&gt;C: Mounts Component</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: Becomes Interactive</span></span></code></pre></div><hr><h2 id="🛡️-security-the-air-gap-strategy" tabindex="-1">🛡️ Security: The &quot;Air-Gap&quot; Strategy <a class="header-anchor" href="#🛡️-security-the-air-gap-strategy" aria-label="Permalink to &quot;🛡️ Security: The &quot;Air-Gap&quot; Strategy&quot;">​</a></h2><p>In a normal React app, one small error or security bug can crash or compromise the <strong>entire</strong> page. We use a strategy called <strong>Island Isolation</strong>.</p><ul><li><strong>Safety Boundaries:</strong> Each interactive section (Island) is independent. If a &quot;Like&quot; button crashes, it won&#39;t break your &quot;Checkout&quot; flow.</li><li><strong>XSS Protection:</strong> Because each &quot;Island&quot; is its own root, it&#39;s much harder for a security vulnerability in one component to peek into or steal data from another.</li></ul><hr><h2 id="🌍-why-the-world-s-best-products-use-this" tabindex="-1">🌍 Why the World&#39;s Best Products use this <a class="header-anchor" href="#🌍-why-the-world-s-best-products-use-this" aria-label="Permalink to &quot;🌍 Why the World&#39;s Best Products use this&quot;">​</a></h2><p>When you build for millions of users, you need two things: <strong>Speed</strong> and <strong>Safety</strong>.</p><ul><li><strong>O(n) Discovery:</strong> Our scanning logic is extremely fast and won&#39;t freeze your user&#39;s browser, even on slow phones.</li><li><strong>Green Memory (Digital Sustainability):</strong> MNCs are now prioritizing ESG (Environmental, Social, and Governance) goals. By avoiding a full-page &quot;Virtual DOM&quot; and only using RAM for active Islands, we reduce the carbon footprint of your application by lowering CPU and battery drain on millions of user devices.</li><li><strong>Low Risk:</strong> You can add React to your existing site one button at a time. No &quot;Big Bang&quot; rewrite required.</li></ul><p><a href="/react-rehydrate/guides/value-proposition.html">Next: Deep Dive into Value Propositions</a></p>`,26)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
